const fs = require('fs');
const { execSync } = require('child_process');

let latestTag;
let latestTagCommit;

try {
	latestTag = execSync('git describe --tags --abbrev=0').toString().trim();
	latestTagCommit = execSync(`git rev-parse ${latestTag}`).toString().trim();
} catch {
	latestTag = 'N/A';
	latestTagCommit = 'N/A';
}

const currentCommit = execSync('git rev-parse HEAD').toString().trim();

const versionInfo = {
	version: latestTag || 'N/A',
	versionCommit: latestTagCommit,
	currentCommit: currentCommit,
};

fs.writeFileSync(
	'./js/version.js',
	`
// Generated by get-version.js
define(function () {
	return ${JSON.stringify(versionInfo, null, 2)};
});
`);
